#pragma once
#include "thinkercad/electronics.hpp"
#include <QPainter>
#include <QPainterPath>
namespace ElectronicsArt {
inline bool paint(QPainter& p,const thinkercad::CircuitPart& part,const thinkercad::CircuitState& state,bool selected){
    using namespace thinkercad;if(part.kind!=PartKind::Module)return false;const auto& d=ModuleRegistry::get(part.model);if(d.bus!="electrical"&&d.implementation!="ws2812")return false;
    p.save();p.scale(6,6);p.setRenderHint(QPainter::Antialiasing);auto box=[&](QRectF r,QColor color,double radius=.3){p.setPen(QPen(color.darker(125),.12));p.setBrush(color);p.drawRoundedRect(r,radius,radius);};
    auto text=[&](QRectF r,QString s,QColor color=Qt::white,double size=1.3){p.setPen(color);QFont font("Sans Serif");font.setPointSizeF(size);p.setFont(font);p.drawText(r,Qt::AlignCenter,s);};
    const auto id=part.model;const QColor plastic("#303636"),metal("#a8afad"),pcb("#3f7161");QRectF body(0,0,d.width,d.height);
    const bool chip=d.implementation=="ota"||id=="as3340"||id=="cem3340"||id=="xr2206"||id=="icl8038"||id=="sn76489"||id=="ay-3-8910"||id=="ym2149f"||id=="6n138"||id=="6n137"||id=="tc7660"||id=="max1044"||id=="icl7660"||d.implementation=="audio-opamp"||id.starts_with("74hc")||id=="cd74hc4067"||id.starts_with("ne55")||(id.starts_with("lm3")&&id!="lm317"&&id!="lm337")||id=="lm741"||id=="4n35";
    auto current=[&](std::string channel){auto it=state.ledCurrent.find(part.id+":"+channel);return it==state.ledCurrent.end()?0.:it->second;};const auto led=QColor(QString::fromStdString(part.color));
    if(d.implementation=="ws2812"){
        const int count=neoPixelCount(part);double width=id=="neopixel-ring"?44.5:id=="neopixel-matrix"?8*parameter(part,"columns",8):id=="neopixel-single"?5:id=="neopixel-strip"?16.6666667*count:5*count;double height=id=="neopixel-ring"?44.5:id=="neopixel-matrix"?8*parameter(part,"rows",8):d.height;
        if(id=="neopixel-ring"){p.setPen(QPen(pcb,7));p.setBrush(Qt::NoBrush);p.drawEllipse(QRectF(3.5,3.5,37.5,37.5));}else box({0,0,width,height},pcb,.3);
        const auto found=state.pixels.find(part.id);for(int i=0;i<count;++i){QPointF center;if(id=="neopixel-ring"){double angle=i*6.283185307/count;center={22.25+18.75*std::sin(angle),22.25-18.75*std::cos(angle)};}else if(id=="neopixel-matrix"){int columns=int(parameter(part,"columns",8)),row=i/columns,col=i%columns;if(row%2)col=columns-1-col;center={4.+col*8,4.+row*8};}else center={(i+.5)*width/count,height/2};box({center.x()-2.5,center.y()-2.5,5,5},QColor("#e5e5d9"),.15);std::uint32_t value=found!=state.pixels.end()&&i<int(found->second.size())?found->second[i]:0;p.setPen(Qt::NoPen);p.setBrush(value?QColor::fromRgb(value):QColor("#747a6d"));p.drawEllipse(center,1.6,1.6);}
    }
    else if(id=="led-matrix"){box(body,plastic);int rows=int(parameter(part,"rows",8)),columns=int(parameter(part,"columns",8));for(int row=1;row<=rows;++row)for(int col=1;col<=columns;++col){p.setPen(Qt::NoPen);p.setBrush(current(std::to_string(row)+":"+std::to_string(col))>1e-5?led:led.darker(350));auto point=QPointF((col-.5)*d.width/columns,(row-.5)*d.height/rows);p.drawEllipse(point,std::min(d.width/columns,d.height/rows)*.32,std::min(d.width/columns,d.height/rows)*.32);}}
    else if(id=="led-bar10"){box(body,QColor("#ecebe1"));for(int i=1;i<=10;++i)box({1,1+(i-1)*2.3,d.width-2,1.7},current(std::to_string(i))>1e-5?led:led.darker(350),.1);}
    else if(id=="clock-display"){box(body,plastic);for(int digit=1;digit<=4;++digit){double x=(digit-1)*12.3;std::array<QLineF,7> segments{QLineF(x+3,3,x+9,3),QLineF(x+9.5,3.5,x+9.5,8),QLineF(x+9.5,10,x+9.5,14.5),QLineF(x+3,15,x+9,15),QLineF(x+2.5,10,x+2.5,14.5),QLineF(x+2.5,3.5,x+2.5,8),QLineF(x+3,9,x+9,9)};for(int i=0;i<7;++i){p.setPen(QPen(current(std::to_string(digit)+":"+std::string(1,char('a'+i)))>1e-5?led:led.darker(350),.8,Qt::SolidLine,Qt::RoundCap));p.drawLine(segments[i]);}}}
    else if(id.starts_with("battery-")){box(body,plastic,1);double cellWidth=id.starts_with("battery-aa-")?14.5:10.5;int cells=int(parameter(part,"cells",id.back()-'0'));for(int i=0;i<cells;++i){box({i*cellWidth+1,1,cellWidth-2,d.height-2},QColor("#4b8d90"),.8);text({i*cellWidth,3,cellWidth,8},i%2?"−":"+",Qt::white,3);}text(body.adjusted(0,d.height*.5,0,0),QString::number(cells*1.5)+" V",Qt::white,2);}
    else if(chip){body.adjust(1,0,-1,0);for(const auto& [name,at]:d.pinPositions){QPointF pin(at.first,at.second);p.setPen(QPen(metal,.48));p.drawLine(pin,QPointF(pin.x()<d.width/2?body.left():body.right(),pin.y()));}box(body,plastic);p.setPen(QPen(QColor("#7e8580"),.15));p.setBrush(Qt::NoBrush);p.drawArc(QRectF(body.center().x()-1,-1,2,2),180*16,180*16);p.save();p.translate(body.center());p.rotate(-90);text({-d.height/2,-1.5,d.height,3},QString::fromStdString(id).toUpper(),QColor("#cdd2c9"),1.2);p.restore();}
    else if(id.starts_with("dip-")){box(body,QColor("#9a3b3d"));int count=std::stoi(id.substr(4)),mask=int(parameter(part,"switches",0));for(int i=0;i<count;++i){box({1.7,1+i*2.54,4.2,1.9},plastic,.15);box({mask&(1<<i)?3.8:2,1.2+i*2.54,1.7,1.5},QColor("#e3e1d7"),.1);}}
    else if(id=="rotary-1p5t"||id=="encoder-600"){p.setPen(QPen(metal,.15));p.setBrush(metal);p.drawEllipse(body);p.setBrush(plastic);p.drawEllipse(body.adjusted(d.width*.3,d.height*.3,-d.width*.3,-d.height*.3));p.save();p.translate(body.center());p.rotate(parameter(part,id=="encoder-600"?"angle":"position",0)*(id=="encoder-600"?1:45));p.setPen(QPen(QColor("#e2dfd1"),.5));p.drawLine(QPointF(0,-d.height*.16),QPointF(0,-d.height*.04));p.restore();}
    else if(id=="pir"){box(body,pcb);p.setPen(QPen(QColor("#cad1c7"),.1));p.setBrush(QColor("#e0e4dc"));p.drawEllipse(QRectF(5,0,22,22));p.setBrush(Qt::NoBrush);for(int i=1;i<4;++i)p.drawEllipse(QRectF(5+i*2,2*i,22-i*4,22-i*4));}
    else if(id=="mq-gas"){box(body,pcb);p.setPen(QPen(metal,.15));p.setBrush(metal);p.drawEllipse(QRectF(2,1,16,16));p.setPen(QPen(QColor("#78827d"),.15));for(int i=0;i<7;++i){p.drawLine(QPointF(4+i*2,4),QPointF(4+i*2,14));p.drawLine(QPointF(4,4+i*1.6),QPointF(16,4+i*1.6));}}
    else if(id=="lemon"||id=="potato"){p.setPen(QPen(QColor("#aa9655"),.15));p.setBrush(QColor(id=="lemon"?"#e1cb61":"#aa8a63"));p.drawEllipse(body);text(body,id=="lemon"?"LEMON":"POTATO",QColor("#4b4937"),3);}
    else if(id=="matrix-patch"){box(body,QColor("#d3cbb7"));int mask=int(parameter(part,"connections",0));for(int row=0;row<4;++row)for(int col=0;col<4;++col){QPointF point((col+1)*d.width/5,(row+1)*d.height/5);p.setPen(QPen(metal,.2));p.setBrush(mask&(1<<(row*4+col))?QColor("#e8b35c"):plastic);p.drawEllipse(point,1.5,1.5);}}
    else if(id=="solar"){box(body,metal,1);box(body.adjusted(1,1,-1,-1),QColor("#334f65"));p.setPen(QPen(QColor("#a0afb6"),.15));for(int x=1;x<6;++x)p.drawLine(QPointF(d.width*x/6,1),QPointF(d.width*x/6,d.height-1));for(int y=1;y<4;++y)p.drawLine(QPointF(1,d.height*y/4),QPointF(d.width-1,d.height*y/4));}
    else if(id=="lm7805"||id=="ld1117v33"||id=="lm317"||id=="lm337"){
        p.setPen(QPen(metal,.65));for(const auto& [name,pin]:d.pinPositions)p.drawLine(QPointF(pin.first,14),QPointF(pin.first,pin.second));
        QRectF package(0,0,10.16,15);box(package,plastic);box({0,0,10.16,5},metal);p.setPen(Qt::NoPen);p.setBrush(QColor("#e5e6df"));p.drawEllipse(QPointF(5.08,2.5),1.5,1.5);text({0,6,10.16,7},QString::fromStdString(id),Qt::white,1.1);
    }
    else if(id=="bulb"){p.setPen(QPen(QColor("#a9b7ae"),.2));p.setBrush(QColor("#d8dfd5"));p.drawEllipse(body.adjusted(0,0,0,-d.height*.25));box({d.width*.3,d.height*.7,d.width*.4,d.height*.3},metal);p.setPen(QPen(QColor("#b08b4d"),.3));p.drawLine(QPointF(d.width*.3,d.height*.4),QPointF(d.width*.7,d.height*.4));}
    else if(id.starts_with("relay-")){box(body,QColor("#3c7391"),.6);text(body,QString::fromStdString(id).toUpper(),Qt::white,1.6);}
    else if(id=="zener"){p.setPen(QPen(metal,.45));p.drawLine(QPointF(0,1.5),QPointF(12.7,1.5));box({3.75,0,5.2,3},QColor("#846351"));box({7.6,0,.65,3},QColor("#c6c8bd"),.05);}
    else if(id=="fsr"||id=="photodiode"){p.setPen(QPen(plastic,.15));p.setBrush(id=="fsr"?QColor("#61726a"):QColor("#606b72"));p.drawEllipse(body);p.setBrush(QColor("#bfc6b9"));p.drawEllipse(body.adjusted(1,1,-1,-1));}
    else if(id=="flex"){box(body,QColor("#a1a187"));p.setPen(QPen(QColor("#5a6257"),.5));for(int y=4;y<d.height-3;y+=4)p.drawLine(QPointF(1,y),QPointF(d.width-1,y));}
    else {const bool connector=id.find("jack")!=std::string::npos||id.find("header")!=std::string::npos||id.find("jst")!=std::string::npos||id.find("terminal")!=std::string::npos||id=="rca"||id=="banana"||id=="dc-barrel"||id=="usb-c-power";box(body,connector?plastic:pcb,.5);if(connector){for(const auto& [pin,at]:d.pinPositions){p.setPen(QPen(metal,.2));p.setBrush(QColor("#151b1a"));p.drawEllipse(QPointF(std::clamp(at.first,1.,d.width-1),d.height/2),.65,.65);}}else{box(body.adjusted(d.width*.25,d.height*.25,-d.width*.25,-d.height*.25),plastic);text({1,d.height*.77,d.width-2,d.height*.2},QString::fromStdString(d.label),QColor("#dae1d8"),1.1);}}
    if(selected){p.setPen(QPen(QColor("#14b8a6"),.2,Qt::DashLine));p.setBrush(Qt::NoBrush);p.drawRoundedRect(QRectF(0,0,d.width,d.height).adjusted(-.6,-.6,.6,.6),.5,.5);}p.restore();return true;
}
}
